import * as React from 'react';
import { Button, Toaster, ToasterComponent, ToasterProvider, useToaster } from '@gravity-ui/uikit';

const toaster = new Toaster();

function CornerButton() {
  const { add } = useToaster();

  const handleClick = () => {
    add({
      name: `toast-${Date.now()}`,   // unique name so repeated clicks stack
      title: 'Готово!',
      content: 'Это уведомление исчезнет само через 5 секунд',
      theme: 'success',
    });
  };

  return (
    <Button view="action" size="l" onClick={handleClick} className="corner-button">
      Показать уведомление
    </Button>
  );
}

export function App() {
  return (
    <ToasterProvider toaster={toaster}>
      <CornerButton />
      <ToasterComponent />
    </ToasterProvider>
  );
}
```

